package dns.resolver

import java.net.InetSocketAddress
import java.nio.ByteBuffer
import java.nio.channels.SocketChannel
import java.security.SecureRandom
import java.util.concurrent.{ConcurrentHashMap, ConcurrentLinkedQueue}
import java.util.concurrent.atomic.{AtomicBoolean, AtomicInteger}
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

case class DnsRecord(name: String, ttl: Int, address: String)
case class DnsQuery(id: Int, name: String, queryType: Int)

trait ConnectionLifecycleListener {
  def onAcquire(conn: PooledConnection): Unit
  def onRelease(conn: PooledConnection): Unit
  def onEvict(conn: PooledConnection): Unit
}

class PooledConnection(
  val channel: SocketChannel,
  val id: Int,
  val createdAt: Long
) {
  val inUse: AtomicBoolean = new AtomicBoolean(false)
  val queryCount: AtomicInteger = new AtomicInteger(0)
  @volatile var lastUsed: Long = System.currentTimeMillis()
  @volatile var pendingCallback: Option[DnsRecord => Unit] = None

  def isExpired(maxAgeMs: Long): Boolean =
    System.currentTimeMillis() - createdAt > maxAgeMs

  def isIdle(idleTimeMs: Long): Boolean =
    System.currentTimeMillis() - lastUsed > idleTimeMs
}

class ConnectionPool(
  val server: InetSocketAddress,
  val maxSize: Int = 8,
  val maxAge: Long = 30000,
  val idleTimeout: Long = 10000
) {
  private val pool = new ConcurrentLinkedQueue[PooledConnection]()
  private val activeCount = new AtomicInteger(0)
  private val connIdGen = new AtomicInteger(0)
  private val listeners = new ConcurrentLinkedQueue[ConnectionLifecycleListener]()

  def addListener(listener: ConnectionLifecycleListener): Unit =
    listeners.add(listener)

  def acquire(): Option[PooledConnection] = {
    var conn = pool.poll()
    while (conn != null && (conn.isExpired(maxAge) || !conn.channel.isConnected)) {
      evictConnection(conn)
      conn = pool.poll()
    }
    if (conn != null) {
      conn.inUse.set(true)
      conn.lastUsed = System.currentTimeMillis()
      notifyAcquire(conn)
      Some(conn)
    } else if (activeCount.get() < maxSize) {
      createConnection()
    } else {
      None
    }
  }

  def release(conn: PooledConnection): Unit = {
    conn.inUse.set(false)
    conn.lastUsed = System.currentTimeMillis()
    notifyRelease(conn)
    if (!conn.isExpired(maxAge) && conn.channel.isConnected) {
      pool.offer(conn)
    } else {
      evictConnection(conn)
    }
  }

  private def createConnection(): Option[PooledConnection] = {
    Try {
      val channel = SocketChannel.open()
      channel.configureBlocking(false)
      channel.connect(server)
      val deadline = System.currentTimeMillis() + 5000
      while (!channel.finishConnect() && System.currentTimeMillis() < deadline) {
        Thread.sleep(10)
      }
      if (!channel.isConnected) {
        channel.close()
        throw new RuntimeException("Connection timeout")
      }
      val conn = new PooledConnection(channel, connIdGen.incrementAndGet(), System.currentTimeMillis())
      activeCount.incrementAndGet()
      conn.inUse.set(true)
      notifyAcquire(conn)
      conn
    }.toOption
  }

  private def evictConnection(conn: PooledConnection): Unit = {
    activeCount.decrementAndGet()
    notifyEvict(conn)
    Try(conn.channel.close())
  }

  private def notifyAcquire(conn: PooledConnection): Unit = {
    val iter = listeners.iterator()
    while (iter.hasNext) iter.next().onAcquire(conn)
  }

  private def notifyRelease(conn: PooledConnection): Unit = {
    val iter = listeners.iterator()
    while (iter.hasNext) iter.next().onRelease(conn)
  }

  private def notifyEvict(conn: PooledConnection): Unit = {
    val iter = listeners.iterator()
    while (iter.hasNext) iter.next().onEvict(conn)
  }
}

class CachingResolver(
  pool: ConnectionPool,
  val cacheSize: Int = 256
) extends ConnectionLifecycleListener {

  private val cache = new ConcurrentHashMap[String, (DnsRecord, Long)]()
  private val inflight = new ConcurrentHashMap[String, PooledConnection]()
  private val retryQueue = new ConcurrentLinkedQueue[(DnsQuery, DnsRecord => Unit)]()
  // Cryptographically strong RNG for DNS transaction IDs to mitigate
  // spoofing / cache poisoning (predictable IDs are guessable).
  private val secureRandom = new SecureRandom()

  pool.addListener(this)

  override def onAcquire(conn: PooledConnection): Unit = {
    // Process retry queue when a connection becomes available
  }

  override def onRelease(conn: PooledConnection): Unit = {
    // On release, schedule retry processing asynchronously
    // Do NOT re-acquire the connection during the release callback
    // to prevent reentrancy issues
  }

  override def onEvict(conn: PooledConnection): Unit = {
    inflight.values().removeIf(c => c.id == conn.id)
  }

  def resolve(name: String, callback: DnsRecord => Unit): Unit = {
    val cached = cache.get(name)
    if (cached != null) {
      val (record, expiry) = cached
      if (System.currentTimeMillis() < expiry) {
        callback(record)
        return
      }
      cache.remove(name)
    }

    val query = DnsQuery(
      id = generateQueryId(),
      name = name,
      queryType = 1 // A record
    )

    pool.acquire() match {
      case Some(conn) =>
        conn.pendingCallback = Some(callback)
        inflight.put(name, conn)
        sendQuery(conn, query)
      case None =>
        retryQueue.offer((query, callback))
    }
  }

  // Unpredictable 16-bit DNS transaction ID (1..65535).
  private def generateQueryId(): Int = secureRandom.nextInt(65535) + 1

  def processRetryQueue(): Unit = {
    var pending = retryQueue.poll()
    while (pending != null) {
      val (query, callback) = pending
      pool.acquire() match {
        case Some(conn) =>
          conn.pendingCallback = Some(callback)
          inflight.put(query.name, conn)
          sendQuery(conn, query)
        case None =>
          retryQueue.offer((query, callback))
          return // stop processing, no connections available
      }
      pending = retryQueue.poll()
    }
  }

  def handleResponse(conn: PooledConnection, record: DnsRecord): Unit = {
    cache.put(record.name, (record, System.currentTimeMillis() + record.ttl * 1000L))
    inflight.remove(record.name)
    conn.pendingCallback.foreach(cb => cb(record))
    conn.pendingCallback = None
    conn.queryCount.incrementAndGet()
    pool.release(conn)
    processRetryQueue()
  }

  def handleTimeout(conn: PooledConnection, query: DnsQuery): Unit = {
    val cb = conn.pendingCallback
    conn.pendingCallback = None
    inflight.remove(query.name)
    cb.foreach(callback => retryQueue.offer((query, callback)))
    pool.release(conn)
    processRetryQueue()
  }

  private def sendQuery(conn: PooledConnection, query: DnsQuery): Unit = {
    val buf = encodeDnsQuery(query)
    Try(conn.channel.write(buf)) match {
      case Success(_) => // wait for response
      case Failure(_) =>
        conn.pendingCallback.foreach(cb => retryQueue.offer((query, cb)))
        conn.pendingCallback = None
        pool.release(conn)
    }
  }

  private def encodeDnsQuery(query: DnsQuery): ByteBuffer = {
    val buf = ByteBuffer.allocate(512)
    buf.putShort(query.id.toShort)
    buf.putShort(0x0100.toShort) // standard query, recursion desired
    buf.putShort(1.toShort) // questions
    buf.putShort(0.toShort) // answers
    buf.putShort(0.toShort) // authority
    buf.putShort(0.toShort) // additional
    val labels = query.name.split('.')
    // Validate DNS name/label constraints to prevent malformed packets
    // (negative length bytes from oversized labels) and buffer overflow.
    var totalNameLen = 0
    labels.foreach { label =>
      val bytes = label.getBytes("ASCII")
      if (bytes.length == 0 || bytes.length > 63)
        throw new IllegalArgumentException("Invalid DNS label length: " + bytes.length)
      totalNameLen += bytes.length + 1
      if (totalNameLen > 255)
        throw new IllegalArgumentException("DNS name exceeds maximum length")
    }
    labels.foreach { label =>
      val bytes = label.getBytes("ASCII")
      buf.put(bytes.length.toByte)
      buf.put(bytes)
    }
    buf.put(0.toByte)
    buf.putShort(query.queryType.toShort)
    buf.putShort(1.toShort) // IN class
    buf.flip()
    buf
  }
}
